            for b in 'ACGU':
                if b == orig: continue
                s = list(seq); s[i] = b; c = ''.join(s)
                dc = dist(c)
                if dc < bd:
                    bd = dc; bs = c
            if bd < d:
                d = bd; seq = bs
            if d == 0: break
        if d < best_d:
            best_d = d
            best_s = seq
        if best_d == 0:
            break
    return best_d, best_s

if __name__ == '__main__':
