                s2[j]=random.choice('ACGU')
        s=''.join(s2)
    if bestscore==len(pairs)*2:
        # check exact
        ss,correct,missing,extra=score(best)
        if correct==len(pairs) and extra==0:
            print("SOLVED",best)
            break

print("bestscore",bestscore)
print("best",best)
ss,correct,missing,extra=score(best)
